// Each tick advances timeStep; one scan owns Mara, Ivo and Noor together.
walkers$ = ticks$.pipe(take(steps), scan((walkers) => {
  old = snapshot(walkers)
  next = old.map((body) => {
    // ordinaryRules is the neighbour lookup and requests above, all reading old.
    separation, cohesion, alignment, cruise = ordinaryRules(body, old)
    acceleration = engine.blend([
      (separationWeight, separation), (cohesionWeight, cohesion),
      (alignmentWeight, alignment), (cruiseWeight, cruise)
    ], maxAcceleration)
    nextVelocity = clipLength(body.velocity + acceleration * timeStep, maxSpeed)
    return body with velocity = nextVelocity, position = body.position + nextVelocity * timeStep
  })
  return next // Emit only after every walker has blended and moved.
}, initialWalkers),
  startWith(initialWalkers), // scan does not emit its seed.
  shareReplay({ bufferSize: 1, refCount: true }) // Share complete frames across views.
)
// Pure rules must preserve old; RxJS neither freezes it nor prevents collisions.

