// frames$ emits Mica’s pre-update snapshot with clearance and travel already computed.
acceleration$ = frames$.pipe(
  concatMap(({ clearance, travel, clearancePriority, epsilon }) => {
    const groups = clearancePriority == 1
      ? [clearance, travel] : [travel, clearance];
    return from(groups).pipe(
      filter(group => length(group) > epsilon),
      take(1),
      defaultIfEmpty(zero)
    );
  })
);
// from emits this ready list synchronously, so list order sets priority.
// take(1) ends only this frame’s inner stream; the next frame starts a fresh choice.
// Apply acceleration in the ordinary velocity/position update before the next snapshot.
// This reading adds no hysteresis or safety guarantee, so changed requests can flip the winner.
// Async results must first share a frame snapshot; first arrival is not priority.

